"use strict";(globalThis.webpackChunkc_users_ksabando_app_data_local_temp_docusaurus_init=globalThis.webpackChunkc_users_ksabando_app_data_local_temp_docusaurus_init||[]).push([[72408],{27413(e,a,s){s.r(a),s.d(a,{assets:()=>c,contentTitle:()=>t,default:()=>u,frontMatter:()=>i,metadata:()=>r,toc:()=>d});const r=JSON.parse('{"id":"cursos/docker/modulos/registros-docker-hub/cuestionario","title":"Cuestionario M09 \u2014 Registros de Im\xe1genes y Docker Hub","description":"Instrucci\xf3n: Estas preguntas eval\xfaan si investigaste m\xe1s all\xe1 del","source":"@site/docs/cursos/docker/modulos/09-registros-docker-hub/cuestionario.md","sourceDirName":"cursos/docker/modulos/09-registros-docker-hub","slug":"/cursos/docker/modulos/registros-docker-hub/cuestionario","permalink":"/sasf-temarios/cursos/docker/modulos/registros-docker-hub/cuestionario","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"sidebar_label":"Cuestionario"},"sidebar":"cursosSidebar","previous":{"title":"Clase","permalink":"/sasf-temarios/cursos/docker/modulos/registros-docker-hub/clase"},"next":{"title":"Ejercicio","permalink":"/sasf-temarios/cursos/docker/modulos/registros-docker-hub/ejercicio"}}');var n=s(74848),o=s(28453);const i={sidebar_label:"Cuestionario"},t="Cuestionario M09 \u2014 Registros de Im\xe1genes y Docker Hub",c={},d=[{value:"1. [Investigar] \xbfC\xf3mo funciona exactamente la OCI Distribution Spec y qu\xe9 endpoints define para push/pull de im\xe1genes? \xbfQu\xe9 diferencia hay entre un blob y un manifest en el modelo de distribuci\xf3n?",id:"1-investigar-c\xf3mo-funciona-exactamente-la-oci-distribution-spec-y-qu\xe9-endpoints-define-para-pushpull-de-im\xe1genes-qu\xe9-diferencia-hay-entre-un-blob-y-un-manifest-en-el-modelo-de-distribuci\xf3n",level:3},{value:"2. [Investigar] \xbfQu\xe9 es exactamente un &quot;manifest list&quot; (o &quot;fat manifest&quot; / OCI Image Index) y c\xf3mo Docker lo usa para im\xe1genes multi-arquitectura? \xbfC\xf3mo se crea y se consulta?",id:"2-investigar-qu\xe9-es-exactamente-un-manifest-list-o-fat-manifest--oci-image-index-y-c\xf3mo-docker-lo-usa-para-im\xe1genes-multi-arquitectura-c\xf3mo-se-crea-y-se-consulta",level:3},{value:"3. [Investigar] \xbfQu\xe9 es Zot y c\xf3mo se posiciona como alternativa ligera a Harbor y registry:2? \xbfQu\xe9 features ofrece para entornos edge y air-gapped?",id:"3-investigar-qu\xe9-es-zot-y-c\xf3mo-se-posiciona-como-alternativa-ligera-a-harbor-y-registry2-qu\xe9-features-ofrece-para-entornos-edge-y-air-gapped",level:3},{value:"4. [Investigar] \xbfQu\xe9 es Notation (Azure/Notary v2) y c\xf3mo se diferencia de Cosign para firmar im\xe1genes OCI? \xbfPor qu\xe9 existen dos est\xe1ndares de firma?",id:"4-investigar-qu\xe9-es-notation-azurenotary-v2-y-c\xf3mo-se-diferencia-de-cosign-para-firmar-im\xe1genes-oci-por-qu\xe9-existen-dos-est\xe1ndares-de-firma",level:3},{value:"5. [Conectar] La clase menciona Harbor. \xbfC\xf3mo se relaciona Harbor con la CNCF y qu\xe9 significa que sea un proyecto &quot;graduado&quot;? \xbfQu\xe9 otros registries son proyectos CNCF?",id:"5-conectar-la-clase-menciona-harbor-c\xf3mo-se-relaciona-harbor-con-la-cncf-y-qu\xe9-significa-que-sea-un-proyecto-graduado-qu\xe9-otros-registries-son-proyectos-cncf",level:3},{value:"6. [Conectar] La clase muestra <code>docker push</code>. \xbfC\xf3mo funciona el chunked upload de blobs grandes y c\xf3mo maneja la reanudaci\xf3n de subidas interrumpidas?",id:"6-conectar-la-clase-muestra-docker-push-c\xf3mo-funciona-el-chunked-upload-de-blobs-grandes-y-c\xf3mo-maneja-la-reanudaci\xf3n-de-subidas-interrumpidas",level:3},{value:"7. [Conectar] \xbfQu\xe9 es el &quot;rate limiting&quot; de Docker Hub y c\xf3mo afecta a equipos de CI/CD? \xbfQu\xe9 estrategias existen para mitigarlo m\xe1s all\xe1 de un proxy cache?",id:"7-conectar-qu\xe9-es-el-rate-limiting-de-docker-hub-y-c\xf3mo-afecta-a-equipos-de-cicd-qu\xe9-estrategias-existen-para-mitigarlo-m\xe1s-all\xe1-de-un-proxy-cache",level:3},{value:"8. [Cuestionar] \xbfDeber\xedas usar siempre un registry privado (Harbor/ECR) en lugar de Docker Hub para im\xe1genes de producci\xf3n? \xbfCu\xe1ndo Docker Hub es aceptable?",id:"8-cuestionar-deber\xedas-usar-siempre-un-registry-privado-harborecr-en-lugar-de-docker-hub-para-im\xe1genes-de-producci\xf3n-cu\xe1ndo-docker-hub-es-aceptable",level:3},{value:"9. [Cuestionar] &quot;Las im\xe1genes multi-arquitectura son el presente, pero el 90% de los builds son amd64&quot;. \xbfVale la pena el esfuerzo de construir para arm64 hoy? \xbfQu\xe9 costo tiene en CI/CD?",id:"9-cuestionar-las-im\xe1genes-multi-arquitectura-son-el-presente-pero-el-90-de-los-builds-son-amd64-vale-la-pena-el-esfuerzo-de-construir-para-arm64-hoy-qu\xe9-costo-tiene-en-cicd",level:3},{value:"10. [Cuestionar] \xbfDebe <code>latest</code> tag ser considerado un antipatr\xf3n? \xbfTiene alg\xfan uso leg\xedtimo en 2025 o deber\xeda ser eliminado de las mejores pr\xe1cticas?",id:"10-cuestionar-debe-latest-tag-ser-considerado-un-antipatr\xf3n-tiene-alg\xfan-uso-leg\xedtimo-en-2025-o-deber\xeda-ser-eliminado-de-las-mejores-pr\xe1cticas",level:3}];function l(e){const a={code:"code",h1:"h1",h3:"h3",header:"header",hr:"hr",p:"p",strong:"strong",...(0,o.R)(),...e.components};return(0,n.jsxs)(n.Fragment,{children:[(0,n.jsx)(a.header,{children:(0,n.jsx)(a.h1,{id:"cuestionario-m09--registros-de-im\xe1genes-y-docker-hub",children:"Cuestionario M09 \u2014 Registros de Im\xe1genes y Docker Hub"})}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.strong,{children:"Instrucci\xf3n"}),": Estas preguntas eval\xfaan si investigaste m\xe1s all\xe1 del\r\ncontenido de la clase. No alcanza con lo visto en ",(0,n.jsx)(a.code,{children:"clase.md"}),".\r\nFundament\xe1 tus respuestas con fuentes, autores o ejemplos concretos."]}),"\n",(0,n.jsx)(a.hr,{}),"\n",(0,n.jsx)(a.h3,{id:"1-investigar-c\xf3mo-funciona-exactamente-la-oci-distribution-spec-y-qu\xe9-endpoints-define-para-pushpull-de-im\xe1genes-qu\xe9-diferencia-hay-entre-un-blob-y-un-manifest-en-el-modelo-de-distribuci\xf3n",children:"1. [Investigar] \xbfC\xf3mo funciona exactamente la OCI Distribution Spec y qu\xe9 endpoints define para push/pull de im\xe1genes? \xbfQu\xe9 diferencia hay entre un blob y un manifest en el modelo de distribuci\xf3n?"}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.strong,{children:"Respuesta"}),": La OCI Distribution Spec (github.com/opencontainers/distribution-spec) define una API REST HTTP para subir y descargar artefactos OCI. Endpoints principales: 1) ",(0,n.jsx)(a.code,{children:"GET /v2/"})," \u2014 verifica que el registry soporta la API, 2) ",(0,n.jsx)(a.code,{children:"GET /v2/&#x3C;name>/manifests/&#x3C;reference>"})," \u2014 descarga el manifest (JSON con referencias a capas y configuraci\xf3n), 3) ",(0,n.jsx)(a.code,{children:"PUT /v2/&#x3C;name>/manifests/&#x3C;reference>"})," \u2014 sube el manifest, 4) ",(0,n.jsx)(a.code,{children:"HEAD /v2/&#x3C;name>/blobs/&#x3C;digest>"})," \u2014 verifica si el blob ya existe (para deduplicaci\xf3n en push), 5) ",(0,n.jsx)(a.code,{children:"GET /v2/&#x3C;name>/blobs/&#x3C;digest>"})," \u2014 descarga un blob (capa comprimida), 6) ",(0,n.jsx)(a.code,{children:"POST /v2/&#x3C;name>/blobs/uploads/"})," \u2014 inicia upload de blob (monolithic o chunked). Un ",(0,n.jsx)(a.strong,{children:"manifest"})," es metadata que referencia los blobs (capas) y la configuraci\xf3n de la imagen por digest SHA256. Un ",(0,n.jsx)(a.strong,{children:"blob"})," es el contenido binario de una capa (tar.gz comprimido) o la configuraci\xf3n de la imagen (JSON). El registry almacena blobs por digest (content-addressable) y los manifiestos por tag."]}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.strong,{children:"Por qu\xe9"}),": La especificaci\xf3n (actualmente v1.1.0-rc1) est\xe1 implementada por Docker Hub, ECR, GCR, ACR, Harbor, Quay, y registry:2. El modelo content-addressable (blobs identificados por digest SHA256) permite deduplicaci\xf3n masiva: si 1000 im\xe1genes usan la misma capa base ",(0,n.jsx)(a.code,{children:"alpine:3.20"}),", el registry almacena el blob UNA vez. El manifest usa mediaTypes para identificar el formato: ",(0,n.jsx)(a.code,{children:"application/vnd.oci.image.manifest.v1+json"})," (OCI) o ",(0,n.jsx)(a.code,{children:"application/vnd.docker.distribution.manifest.v2+json"})," (Docker). La spec tambi\xe9n define el manejo de rate limits, paginaci\xf3n de tags, y eliminaci\xf3n de manifests (soft delete con referencia al digest)."]}),"\n",(0,n.jsx)(a.hr,{}),"\n",(0,n.jsx)(a.h3,{id:"2-investigar-qu\xe9-es-exactamente-un-manifest-list-o-fat-manifest--oci-image-index-y-c\xf3mo-docker-lo-usa-para-im\xe1genes-multi-arquitectura-c\xf3mo-se-crea-y-se-consulta",children:'2. [Investigar] \xbfQu\xe9 es exactamente un "manifest list" (o "fat manifest" / OCI Image Index) y c\xf3mo Docker lo usa para im\xe1genes multi-arquitectura? \xbfC\xf3mo se crea y se consulta?'}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.strong,{children:"Respuesta"}),": Un manifest list (llamado OCI Image Index en la OCI Image Spec) es un JSON de alto nivel que contiene una lista de descriptores de manifiestos, cada uno con la plataforma destino (",(0,n.jsx)(a.code,{children:"os"}),", ",(0,n.jsx)(a.code,{children:"architecture"}),", ",(0,n.jsx)(a.code,{children:"variant"}),", ",(0,n.jsx)(a.code,{children:"os.version"}),"). Al hacer pull, el cliente Docker env\xeda su OS y arquitectura en los headers HTTP Accept. El registry selecciona el manifiesto correspondiente y lo devuelve. El manifest list se crea con ",(0,n.jsx)(a.code,{children:"docker buildx build --platform linux/amd64,linux/arm64"})," (que genera autom\xe1ticamente el index), o manualmente con ",(0,n.jsx)(a.code,{children:"docker manifest create"}),". Se consulta con ",(0,n.jsx)(a.code,{children:"docker manifest inspect"})," o ",(0,n.jsx)(a.code,{children:"docker buildx imagetools inspect"}),", que muestra cada entrada del index con su plataforma, digest, y tama\xf1o."]}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.strong,{children:"Por qu\xe9"}),": El OCI Image Index (definido en image-spec v1.0) usa mediaType ",(0,n.jsx)(a.code,{children:"application/vnd.oci.image.index.v1+json"}),". Docker Hub, ECR, GCR, y otros registries soportan manifest lists nativamente. La ventaja es transparencia total para el usuario: ",(0,n.jsx)(a.code,{children:"docker run nginx:latest"})," en un M1 Mac (arm64) y en un servidor AMD64 descargan im\xe1genes diferentes del mismo tag. El registry resuelve la plataforma autom\xe1ticamente. Los fields opcionales del descriptor incluyen ",(0,n.jsx)(a.code,{children:"annotations"})," para metadata (ej. ",(0,n.jsx)(a.code,{children:"vnd.docker.reference.digest"}),"), y ",(0,n.jsx)(a.code,{children:"urls"})," para descargar el blob desde una URL externa (poco usado en la pr\xe1ctica). Buildx con QEMU permite construir para m\xfaltiples plataformas desde un solo runner."]}),"\n",(0,n.jsx)(a.hr,{}),"\n",(0,n.jsx)(a.h3,{id:"3-investigar-qu\xe9-es-zot-y-c\xf3mo-se-posiciona-como-alternativa-ligera-a-harbor-y-registry2-qu\xe9-features-ofrece-para-entornos-edge-y-air-gapped",children:"3. [Investigar] \xbfQu\xe9 es Zot y c\xf3mo se posiciona como alternativa ligera a Harbor y registry:2? \xbfQu\xe9 features ofrece para entornos edge y air-gapped?"}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.strong,{children:"Respuesta"}),": Zot (de Cisco/Project Zot) es un registry OCI open-source escrito en Go, dise\xf1ado para ser ligero, seguro, y funcionar en entornos edge/air-gapped. A diferencia de Harbor (que es un producto enterprise con UI web, m\xfaltiples servicios, DB, Redis), Zot es un solo binario (~50 MB) con: 1) escaneo de vulnerabilidades integrado (Trivy), 2) firmas Cosign/Notation integradas, 3) sincronizaci\xf3n entre registries (\xfatil para edge: sync de un registry central a nodos edge), 4) garbage collection eficiente, 5) interfaz web m\xednima (zui), 6) soporte para almacenamiento local y S3. Para entornos air-gapped: Zot se despliega como un solo binario sin dependencias externas, sincroniza im\xe1genes desde un registry conectado v\xeda sneakernet (USB), y escanea localmente sin internet."]}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.strong,{children:"Por qu\xe9"}),': Zot fue presentado en KubeCon 2022 y es un proyecto abierto bajo Apache 2.0. La motivaci\xf3n: Harbor es excelente pero es pesado para edge (requiere ~2 GB RAM, PostgreSQL, Redis). Zot apunta a IoT, sucursales bancarias, f\xe1bricas, y entornos donde correr un cluster K8s solo para el registry no es viable. La caracter\xedstica de sync (pull-based y push-based) est\xe1 dise\xf1ada para "hub and spoke": un Zot central en el data center, Zots edge en cada sucursal, sincronizando solo las im\xe1genes necesarias. Tambi\xe9n soporta OCI artifacts (SBOM, firmas, Helm charts) y es compliant con OCI Distribution Spec.']}),"\n",(0,n.jsx)(a.hr,{}),"\n",(0,n.jsx)(a.h3,{id:"4-investigar-qu\xe9-es-notation-azurenotary-v2-y-c\xf3mo-se-diferencia-de-cosign-para-firmar-im\xe1genes-oci-por-qu\xe9-existen-dos-est\xe1ndares-de-firma",children:"4. [Investigar] \xbfQu\xe9 es Notation (Azure/Notary v2) y c\xf3mo se diferencia de Cosign para firmar im\xe1genes OCI? \xbfPor qu\xe9 existen dos est\xe1ndares de firma?"}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.strong,{children:"Respuesta"}),": Notation (github.com/notaryproject/notation) es el sucesor de Docker Notary (v1), impulsado por Microsoft/Azure, Amazon, y Docker. Usa el framework de firma de la OCI (Notary Project) y almacena firmas como OCI artifacts asociados a la imagen via el campo ",(0,n.jsx)(a.code,{children:"subject"})," del manifiesto (OCI Image Spec v1.1). Cosign (Sigstore, Google/Chainguard) usa un enfoque m\xe1s simple: firma la imagen y sube la firma como un tag adicional (",(0,n.jsx)(a.code,{children:".sig"}),"), o como artifact OCI si el registry soporta spec v1.1. Ambos logran el mismo objetivo (integridad + autenticidad), pero difieren en: 1) Cosign soporta keyless signing (OIDC + Rekor transparency log), 2) Notation usa certificados X.509 y PKI tradicional (m\xe1s enterprise-friendly), 3) Notation es m\xe1s nativo del ecosistema azure/ORAS, Cosign del ecosistema Google/Sigstore. La industria converge lentamente: Harbor soporta ambos."]}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.strong,{children:"Por qu\xe9"}),': La bifurcaci\xf3n de est\xe1ndares de firma refleja la tensi\xf3n entre "simple y web-native" (Sigstore/Cosign) y "enterprise PKI compliant" (Notation). Cosign fue pionero en keyless signing (firm\xe1s con tu identidad de GitHub/Google OIDC sin manejar claves privadas). Notation surgi\xf3 de la necesidad de cumplir con requisitos enterprise (HSM, CA internas, pol\xedticas de firma basadas en certificados). La OCI Image Spec v1.1 (abril 2024) estandariz\xf3 c\xf3mo referenciar artefactos relacionados (firma, SBOM) a trav\xe9s del campo ',(0,n.jsx)(a.code,{children:"subject"}),", que ambos proyectos ahora soportan. La elecci\xf3n pr\xe1ctica depende del ecosistema de confianza de la organizaci\xf3n."]}),"\n",(0,n.jsx)(a.hr,{}),"\n",(0,n.jsx)(a.h3,{id:"5-conectar-la-clase-menciona-harbor-c\xf3mo-se-relaciona-harbor-con-la-cncf-y-qu\xe9-significa-que-sea-un-proyecto-graduado-qu\xe9-otros-registries-son-proyectos-cncf",children:'5. [Conectar] La clase menciona Harbor. \xbfC\xf3mo se relaciona Harbor con la CNCF y qu\xe9 significa que sea un proyecto "graduado"? \xbfQu\xe9 otros registries son proyectos CNCF?'}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.strong,{children:"Respuesta"}),": Harbor se uni\xf3 a la CNCF en 2018 como proyecto Sandbox, pas\xf3 a Incubating en 2019, y se gradu\xf3 en 2022. La graduaci\xf3n significa que cumple con criterios estrictos de: adopci\xf3n (miles de organizaciones us\xe1ndolo en producci\xf3n), gobernanza (mantenedores de m\xfaltiples compa\xf1\xedas: VMware, Alibaba, NetEase), madurez del c\xf3digo (CI/CD, seguridad, releases regulares), y comunidad (conferencias, meetups, contribuidores globales). Harbor es el primer registry de contenedores graduado en CNCF. Otros registries en CNCF: Dragonfly (P2P image distribution, Sandbox), Kraken (Uber, P2P registry, Sandbox). Zot no est\xe1 en CNCF a\xfan."]}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.strong,{children:"Por qu\xe9"}),": La CNCF (Cloud Native Computing Foundation) alberga proyectos cloud-native. La graduaci\xf3n es el nivel m\xe1s alto de madurez (Kubernetes, Prometheus, Envoy, Helm, Harbor). Para Harbor, la graduaci\xf3n valid\xf3 que es un est\xe1ndar enterprise para registry on-prem. El proceso de graduaci\xf3n incluye due diligence de seguridad (auditor\xeda externa), adopci\xf3n documentada (Harbor report\xf3 20,000+ organizaciones usando), y diversidad de contribuidores. La alternativa m\xe1s cercana en CNCF es usar distribution/distribution (registry:2 de Docker, proyecto CNCF Sandbox) y construir features enterprise encima, pero Harbor ya provee todo integrado."]}),"\n",(0,n.jsx)(a.hr,{}),"\n",(0,n.jsxs)(a.h3,{id:"6-conectar-la-clase-muestra-docker-push-c\xf3mo-funciona-el-chunked-upload-de-blobs-grandes-y-c\xf3mo-maneja-la-reanudaci\xf3n-de-subidas-interrumpidas",children:["6. [Conectar] La clase muestra ",(0,n.jsx)(a.code,{children:"docker push"}),". \xbfC\xf3mo funciona el chunked upload de blobs grandes y c\xf3mo maneja la reanudaci\xf3n de subidas interrumpidas?"]}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.strong,{children:"Respuesta"}),": ",(0,n.jsx)(a.code,{children:"docker push"})," usa el protocolo de upload de la OCI Distribution Spec. Para blobs grandes (capas de cientos de MB): 1) ",(0,n.jsx)(a.code,{children:"POST /v2/&#x3C;name>/blobs/uploads/"})," \u2014 inicia la sesi\xf3n de upload, el registry devuelve un ",(0,n.jsx)(a.code,{children:"Location"})," header con un UUID de sesi\xf3n, 2) ",(0,n.jsx)(a.code,{children:"PATCH /v2/&#x3C;name>/blobs/uploads/&#x3C;uuid>"})," \u2014 env\xeda chunks del blob (Content-Range header), el registry acumula los chunks, 3) ",(0,n.jsx)(a.code,{children:"PUT /v2/&#x3C;name>/blobs/uploads/&#x3C;uuid>?digest=&#x3C;sha256:...>"})," \u2014 finaliza el upload con el digest esperado, el registry verifica que el contenido matchea el digest. Si la conexi\xf3n se interrumpe, el cliente puede hacer ",(0,n.jsx)(a.code,{children:"GET /v2/&#x3C;name>/blobs/uploads/&#x3C;uuid>"})," para obtener el offset actual (cu\xe1ntos bytes ya recibi\xf3 el registry) y continuar desde ah\xed con otro PATCH. Las sesiones de upload expiran despu\xe9s de un tiempo configurable (default 24h en registry:2)."]}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.strong,{children:"Por qu\xe9"}),': La OCI Distribution Spec (v1.1) detalla este protocolo en la secci\xf3n "Pushing Blobs". El chunked upload permite: subir im\xe1genes de m\xfaltiples GB sin riesgo de timeout en una sola conexi\xf3n, y reanudar desde el punto de interrupci\xf3n sin reenviar datos ya subidos. Docker CLI y containerd implementan esto autom\xe1ticamente. El digest final debe coincidir (el registry lo recalcula) para prevenir corrupci\xf3n. Algunos registries (ECR) prefieren single-request upload para blobs peque\xf1os (< 10 MB) por simplicidad. La sesi\xf3n de upload (UUID) es temporal y garbage-collected si no se completa.']}),"\n",(0,n.jsx)(a.hr,{}),"\n",(0,n.jsx)(a.h3,{id:"7-conectar-qu\xe9-es-el-rate-limiting-de-docker-hub-y-c\xf3mo-afecta-a-equipos-de-cicd-qu\xe9-estrategias-existen-para-mitigarlo-m\xe1s-all\xe1-de-un-proxy-cache",children:'7. [Conectar] \xbfQu\xe9 es el "rate limiting" de Docker Hub y c\xf3mo afecta a equipos de CI/CD? \xbfQu\xe9 estrategias existen para mitigarlo m\xe1s all\xe1 de un proxy cache?'}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.strong,{children:"Respuesta"}),": Docker Hub impone rate limits basados en IP (para pulls an\xf3nimos) y en cuenta (para pulls autenticados). L\xedmites actuales (2024): 100 pulls/6h por IP an\xf3nima, 200 pulls/6h para cuentas gratuitas autenticadas, 1,000-5,000 para Pro/Team, ilimitados para Business. En CI/CD, cada job que hace ",(0,n.jsx)(a.code,{children:"docker build"})," puede requerir m\xfaltiples pulls (imagen base, dependencias en multi-stage), y con 20 desarrolladores + CI runners, se excede f\xe1cilmente. Estrategias m\xe1s all\xe1 del proxy cache: 1) Autenticaci\xf3n siempre en CI (sube el l\xedmite de 100 a 200 aunque no alcance), 2) Usar im\xe1genes base cacheadas en el runner (BuildKit cache con registry backend), 3) Migrar a un registry alternativo (ghcr.io, ECR Public, Quay) que no tiene rate limits para pulls p\xfablicos, 4) Usar ",(0,n.jsx)(a.code,{children:"--pull=never"})," en builds con im\xe1genes locales pre-cargadas."]}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.strong,{children:"Por qu\xe9"}),": Docker Hub anunci\xf3 los rate limits en 2020 (anuncio, luego implementaci\xf3n en noviembre 2020) causando caos en CI/CD. La comunidad reaccion\xf3 moviendo im\xe1genes base a ghcr.io, ECR Public, o usando mirror proxies (Harbor proxy cache, registry:2 con proxy). Para CI/CD, el enfoque m\xe1s robusto es: cachear la imagen base en el registry privado y referenciarla desde ah\xed (no desde Docker Hub), o usar ",(0,n.jsx)(a.code,{children:"cache-to: type=registry"})," y ",(0,n.jsx)(a.code,{children:"cache-from: type=registry"})," en BuildKit para reutilizar capas ya subidas al registry privado. GitHub Actions tambi\xe9n ofrece cache integrada (type=gha) que reduce pulls externos."]}),"\n",(0,n.jsx)(a.hr,{}),"\n",(0,n.jsx)(a.h3,{id:"8-cuestionar-deber\xedas-usar-siempre-un-registry-privado-harborecr-en-lugar-de-docker-hub-para-im\xe1genes-de-producci\xf3n-cu\xe1ndo-docker-hub-es-aceptable",children:"8. [Cuestionar] \xbfDeber\xedas usar siempre un registry privado (Harbor/ECR) en lugar de Docker Hub para im\xe1genes de producci\xf3n? \xbfCu\xe1ndo Docker Hub es aceptable?"}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.strong,{children:"Respuesta"}),": Para producci\xf3n, un registry privado (o gestionado: ECR, ACR, GAR) es preferible porque: 1) Control total sobre disponibilidad (sin rate limits ni dependencia de la infraestructura de Docker Inc.), 2) Compliance (datos en tu regi\xf3n/VPC, auditor\xeda), 3) Seguridad adicional (escaneo integrado, firma de im\xe1genes), 4) Integraci\xf3n con IAM cloud (roles en lugar de credenciales est\xe1ticas). Docker Hub es aceptable para: im\xe1genes oficiales de infraestructura base (nginx, postgres, redis) usadas en desarrollo/staging, im\xe1genes de proyectos open-source p\xfablicos, y cuando el costo/complejidad de mantener un registry privado no se justifica (proyectos personales, MVPs). Para producci\xf3n: SIEMPRE tener un registry que controles (incluso si es un mirror proxy de Docker Hub con Harbor que cachea y escanea)."]}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.strong,{children:"Por qu\xe9"}),": La dependencia de un servicio externo para el runtime de producci\xf3n es un riesgo operativo. Si Docker Hub est\xe1 ca\xeddo (ha tenido outages, ej. noviembre 2020), tus deploys fallan (no pueden hacer pull de im\xe1genes). Si cambi\xe1s de tag ",(0,n.jsx)(a.code,{children:"latest"}),", tus Pods pueden descargar versiones inesperadas. Los registries cloud (ECR, ACR) son altamente disponibles (multi-AZ) y se integran con IAM (sin credenciales est\xe1ticas). El costo de ECR es bajo (~$0.10/GB/mes + transferencia). Para startups, ghcr.io es gratis para repositorios p\xfablicos e ilimitado para privados, integrado con GitHub."]}),"\n",(0,n.jsx)(a.hr,{}),"\n",(0,n.jsx)(a.h3,{id:"9-cuestionar-las-im\xe1genes-multi-arquitectura-son-el-presente-pero-el-90-de-los-builds-son-amd64-vale-la-pena-el-esfuerzo-de-construir-para-arm64-hoy-qu\xe9-costo-tiene-en-cicd",children:'9. [Cuestionar] "Las im\xe1genes multi-arquitectura son el presente, pero el 90% de los builds son amd64". \xbfVale la pena el esfuerzo de construir para arm64 hoy? \xbfQu\xe9 costo tiene en CI/CD?'}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.strong,{children:"Respuesta"}),": Para aplicaciones de servidor (que corren en cloud, mayoritariamente AMD64), el esfuerzo puede ser bajo si ten\xe9s CI runners AMD64 con QEMU (gratis, pero lento) o runners nativos ARM64. El costo en CI: 1) Tiempo: QEMU emulaci\xf3n de ARM en AMD es ~4x m\xe1s lenta que build nativa (un build de 5 min puede tomar 20 min), 2) Si us\xe1s runners nativos ARM (Graviton en AWS, Apple Silicon en Mac), el costo es similar pero necesit\xe1s CI runners duales. Para aplicaciones que los usuarios ejecutan localmente (Docker Desktop en Mac M1/M2/M3, que son ARM64), es ESENCIAL: sin imagen ARM64, los usuarios de Mac con Apple Silicon corren la imagen AMD64 bajo emulaci\xf3n de Rosetta 2 o QEMU, con rendimiento degradado (2-5x m\xe1s lento). Para im\xe1genes de servidor (corren en AMD64 en la nube), no es urgente pero es future-proofing (Graviton es cada vez m\xe1s popular)."]}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.strong,{children:"Por qu\xe9"}),": Docker Desktop en Apple Silicon (M1, 2020) cambi\xf3 el panorama: de repente, todos los desarrolladores con Mac nuevos ten\xedan ARM64. Si tu imagen CLI o herramienta de desarrollo no tiene build ARM64, la experiencia del usuario es mala. La encuesta de Docker (2024) muestra que ~35% de desarrolladores usan Apple Silicon. Para servidores, AWS Graviton (ARM64) ofrece 20-40% mejor precio/rendimiento que AMD64, y su adopci\xf3n crece. La recomendaci\xf3n: si tu imagen es para desarrollo o tooling, multi-arch ES obligatorio. Si es solo para producci\xf3n cloud en AMD64, pod\xe9s posponerlo pero arquitectura tu CI para soportarlo cuando sea necesario (Buildx con QEMU es el primer paso barato)."]}),"\n",(0,n.jsx)(a.hr,{}),"\n",(0,n.jsxs)(a.h3,{id:"10-cuestionar-debe-latest-tag-ser-considerado-un-antipatr\xf3n-tiene-alg\xfan-uso-leg\xedtimo-en-2025-o-deber\xeda-ser-eliminado-de-las-mejores-pr\xe1cticas",children:["10. [Cuestionar] \xbfDebe ",(0,n.jsx)(a.code,{children:"latest"})," tag ser considerado un antipatr\xf3n? \xbfTiene alg\xfan uso leg\xedtimo en 2025 o deber\xeda ser eliminado de las mejores pr\xe1cticas?"]}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.strong,{children:"Respuesta"}),": ",(0,n.jsx)(a.code,{children:"latest"})," es un antipatr\xf3n en producci\xf3n porque: 1) es mutable (cada push sobreescribe) y no determin\xedstico (dos deploys con el mismo tag pueden descargar im\xe1genes diferentes), 2) K8s con ",(0,n.jsx)(a.code,{children:"imagePullPolicy: IfNotPresent"})," no re-descarga aunque el contenido de ",(0,n.jsx)(a.code,{children:"latest"})," haya cambiado, causando drift de versiones entre Pods, 3) Es imposible saber qu\xe9 commit/SHA exacto est\xe1 corriendo en producci\xf3n. Su uso leg\xedtimo en 2025: desarrollo local r\xe1pido (donde siempre quer\xe9s la \xfaltima versi\xf3n), documentaci\xf3n de ejemplos (para simplificar comandos), y im\xe1genes de herramientas CLI que el usuario construye localmente. En CI/CD y producci\xf3n: siempre usar SHA digest (",(0,n.jsx)(a.code,{children:"myapp@sha256:abc..."}),") o tag sem\xe1ntico inmutable (",(0,n.jsx)(a.code,{children:"v1.2.3"}),"). La tendencia es: en K8s, usar digest en lugar de tag mutable."]}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.strong,{children:"Por qu\xe9"}),": La documentaci\xf3n de Kubernetes recomienda evitar ",(0,n.jsx)(a.code,{children:"latest"})," en producci\xf3n. La funci\xf3n original de ",(0,n.jsx)(a.code,{children:"latest"})," era conveniencia (si no especific\xe1s tag, Docker usa ",(0,n.jsx)(a.code,{children:"latest"}),' por defecto). Pero el nombre sugiere "\xfaltima versi\xf3n" cuando en realidad es "lo \xfaltimo que se subi\xf3 con este tag", que puede ser una versi\xf3n rota o incompleta. Herramientas como Hadolint emiten warning DL3007 si us\xe1s ',(0,n.jsx)(a.code,{children:"latest"})," en FROM. La pr\xe1ctica moderna: en Dockerfile, siempre especificar tag expl\xedcito (",(0,n.jsx)(a.code,{children:"FROM node:20.11.1-alpine"}),", no ",(0,n.jsx)(a.code,{children:"FROM node:latest"}),"). En deploys, usar el SHA del commit como tag de imagen y el digest para referenciar la imagen exacta en los manifiestos."]})]})}function u(e={}){const{wrapper:a}={...(0,o.R)(),...e.components};return a?(0,n.jsx)(a,{...e,children:(0,n.jsx)(l,{...e})}):l(e)}},28453(e,a,s){s.d(a,{R:()=>i,x:()=>t});var r=s(96540);const n={},o=r.createContext(n);function i(e){const a=r.useContext(o);return r.useMemo(function(){return"function"==typeof e?e(a):{...a,...e}},[a,e])}function t(e){let a;return a=e.disableParentContext?"function"==typeof e.components?e.components(n):e.components||n:i(e.components),r.createElement(o.Provider,{value:a},e.children)}}}]);